items = []


def add(name, role, axes, milestone, body, exec_class='EXEC-AUTHORIZED'):
    scope = ('Execution class: EXEC-AUTHORIZED — the commands named in this item, and no other.\n'
             if exec_class == 'EXEC-AUTHORIZED' else
             'Execution class: NO-EXEC — read/grep/glob only.\nScope: executed=none\n')
    items.append({'name': name, 'role': role, 'axes': axes, 'milestone': milestone,
                  'prompt': GODSPEED + '\n' + scope + body.strip()})


def row_check_body(seat, role, row, counted):
    fmt = (f"""BINDING FORMAT — the report file is what counts, exactly these first two lines with no wrapper, fence, bullet or JSON:
line 1: `ROW {row} VERDICT: holds|partly|fails`
line 2: `SECTION SHA256: <the 64-hex hash above>`
then the body (>= 300 bytes) citing at least TWO distinct row source files by `file:line` that exist in the pinned snapshots (a citation that resolves nowhere earns nothing): each clause you checked, every defect with its exact replacement text (a defect makes the verdict `partly`, a contradicted clause `fails`), and what you did not check. A `partly` or `fails` blocks the row whatever its citations — report it honestly rather than softening it."""
           if counted else
           f"""This is an UNCOUNTED pre-read: its negatives are fixed in the pre-w2 amendment, never scored. Report format: line 1 `VERDICT: <supports|defect-found>`, line 2 `SECTION SHA256: <hash>`, then every defect as: clause (quote the entry's words), the pinned line that contradicts or fails to support it (`file:line` plus the located text), and the EXACT replacement wording that would make the clause true and fully supported. Also list every claim you checked and found supported, so the L1 knows what was read. Prefer fewer, certain defects over speculative ones; mark an inference as [inference].""")
    return f"""
Item {'C1-COUNTED' if counted else 'C1-PREREAD'} ({seat}, {role}, claim C1). Read row {row} of {L}/{ENTRY} at revision {REV} and decide whether it is admissible knowledge. You did not write it and you are not its author.
Extract the entry once: `mkdir -p {SC}/{seat} && git -C {L} show {REV}:{ENTRY} > {SC}/{seat}/entry.md`, then read ONLY the lines of row {row} (the section from `## {row}` up to the next line beginning `## `), plus the `### Range gaps (R51)` block and the Limits section for context. Confirm the section hash yourself: `python3 {L}/{C1C} --revision {REV} --section-hash --no-base-check` prints {HASH[row]} for {row}; if yours differs, say so and stop.
Pinned sources: {ROWSRC[row]}. Verify their digests first (`sha256sum -c SHA256SUMS` in each snapshot directory, or compare against the recorded lines) and say which snapshot file belongs to which S-row. Run `python3 {L}/{LINT} --revision {REV}` and report its counts (it checks whole-line quotes, resolution of every prose `file:line` and the gap block mechanically; it does NOT check that a clause is true).
Your job as {role}: check every CLAUSE of the row against the pinned bytes — the errno order and each condition, each range (a range that runs into the next function is a defect), each `file:line` citation (does the cited line SUPPORT the clause it is cited for, not merely exist), each Quote, each `[inference]` mark (is the marked sentence really undecided by the pinned bytes, and is any unmarked sentence actually an inference), every word like "first", "only", "any", "always" (is the universal true over the pinned code), and every host claim against {CAP45}/capture.txt. Rows GR2 and GR3 cite more lines than they quote: open the cited lines, not just the quoted ones. {'Read as a hostile reviewer: ' if role == 'critic' else 'Read as a careful reviewer: '}the bar is that a clause survives a reader who opens the cited line.
{fmt}""".strip()


